<?php
declare(strict_types=1);
/** Actual canonical entity helpers; valid UTF-8 no-mention plain cases only. */
function ap_fix_utf8(string $text):string{return $text;}
$hashes=[];
$functions=['ap-masto-entities.php'=>['ap_masto_normalize_tag_name','ap_masto_tag_url','ap_masto_linkify_hashtags_escaped','ap_masto_linkify_hashtags_in_html','ap_masto_repair_at_hash_tags','ap_masto_unglue_bare_handles','ap_masto_unglue_host_mentions','ap_masto_content_with_mentions'],'ap-db.php'=>['ap_normalize_status_html','ap_normalize_bridgy_plain_mentions','ap_plain_unglue_mentions']];
foreach($functions as $file=>$names){$source=(string)file_get_contents(dirname(__DIR__).'/'.$file);foreach($names as $name){if(!preg_match('/^function '.preg_quote($name,'/').'\(.*?^}/ms',$source,$m))throw new RuntimeException($name);eval($m[0]);$hashes[$name]=hash('sha256',$m[0]);}}
$captures=[];$plain=['#Hello #hello #世界','foo#tag bar/#tag &amp;#tag %#tag (##one)',"#Äpfel #İ #Σ #123_",'https://example.test/path#fragment #real',"line #one\nline #two\n\n#three",'&lt;div&gt; #safe &quot;tag&quot;','punctuation!#tag.#again',str_repeat('x',3).' #'.str_repeat('a',101),'#tag#next ##tag','',"\u{00a0}#tag\u{00a0}"];
$html=['<p>#Hello #hello</p>','<p><a href="https://example.test/#fragment">#inside</a> #outside</p>','<p>https://example.test/#fragment #outside</p>','<p><a href="https://mkultra.monster/tags/Test" class="mention hashtag">#<span>Test</span></a> #other</p>',"<p><a href='https://example.test/tags' class='mention hashtag'>#One</a> #Two</p>",'<p>#世界 <strong>#Äpfel</strong></p>'];
foreach($plain as $input){if(str_contains(html_entity_decode($input,ENT_QUOTES|ENT_HTML5,'UTF-8'),'@'))throw new RuntimeException('undeclared SQL mention branch');$captures[]=['helper'=>'plain_pack','input'=>$input,'expected'=>ap_masto_content_with_mentions($input)];$captures[]=['helper'=>'escaped_tags','input'=>htmlspecialchars($input,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'),'expected'=>ap_masto_linkify_hashtags_escaped(htmlspecialchars($input,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'))];}
foreach($html as $input)$captures[]=['helper'=>'html_tags','input'=>$input,'expected'=>ap_masto_linkify_hashtags_in_html($input)];
$out=$argv[1]??'/tmp/vaak-profile-entity-helper-reference.json';file_put_contents($out,json_encode(['captures'=>$captures,'declaration_sha256'=>$hashes,'scope'=>'actual pure canonical hashtag/entity helper branches; SQL mention resolution excluded and remains unfinished'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));echo count($captures)." actual canonical entity helper cases: $out\n";
